<template>
<section class="main-content">
    <div class="my-popups">
        <div class="modal d-block">
            <div class="modal-dialog modal-dialog-centered">
                <div class="modal-content">
                    <div class="modal-header">
                        <h5 class="modal-title">
                            {{ $t('RelatedProduct') }}
                        </h5>
                        <button v-on:click="ClosePopup()" type="button" class="close" data-original-title="Close"><em class="fa fa-times"></em></button>
                    </div>

                    <div class="row">
                        <div class="col-lg-12">
                            <div class="listing">
                                <div class="table-responsive table-fix-header">
                                    <table id="tblRelatedDataItems" class="table table-bordered dt-responsive nowrap my-0">
                                        <thead class="thead-bg">
                                            <tr>
                                                <th><span style="max-width: 7px;">#</span></th>
                                                <th><span>Product Name</span></th>
                                                <th style="min-width: 300px;"><span>Available Quantity</span></th>
                                                <th><span>Required Quantity</span></th>
                                            </tr>
                                        </thead>
                                        <tbody>

                                            <tr v-for="item in GetRelatedProductData" v-bind:key="item">

                                                <td class="text-center">
                                                    <div class="custom-control custom-checkbox">
                                                        <input class="custom-control-input" type="checkbox" name="checkbox" v-model="item.isSelected" v-on:change="singleSelect($event, item)">

                                                        <label class="custom-control-label universal-custom-control-label pt-1"></label>
                                                    </div>
                                                </td>

                                                <td>{{ item.NAME }}</td>
                                                <td>{{ item.AVAILIABLE_ITEM }}</td>
                                                <td>

                                                    <Field name="Quantity" :rules="{ 'required': true }" v-slot="{ errors }">
                                                        <input inputmode="numeric" v-on:keyup="checkQuantity(item, item.Quantity, index)" id="" v-model="item.Quantity" min="1" maxlength="8" v-bind:class="{ 'txtitems form-control ': true, 'is-invalid': errors[0] || item.Quantity == 0 ? true : false }" />
                                                        <span v-if="errors[0]" name="Location" class="invalid-feedback d-block">{{ errors[0] }}</span>
                                                    </Field>

                                                </td>
                                            </tr>

                                        </tbody>
                                    </table>
                                </div>
                            </div>
                            <div class="modal-footer">
                                <button type="button" class="btn btn-danger" @click="ClosePopup">{{ $t('Close')}}</button>
                                <button type="button" id="relatedprdct" class="btn btn-success" @click="SaveChanges">{{$t('SaveChanges') }}</button>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </div>
</section>
</template>

<script>
import DataService from '../../service/DataService';
export default {
    props: {
        RelatedProductDaata: {
            type: Array,
            required: true
        },
        AssetListData: {
            type: Array,
            required: true
        },
        GetRelatedProduct: {
            type: Array
        },
        ItemIndex: {
            type: Number
        },
        issueTo: {
            type: Number,            
        },
        DateofAssignment:{
            type: String,
        },
        DateofAssignmentTillDate:{
            type: String,
        }        
    },
    data() {
        return {
            widgets: [],
            leftSearchFields: '',
            listheaderbuttons: [],
            LegendArray: [],
            GetRelatedProductData: [],
            IsChecked: false,
            txtAssetQuentity: 1,
            RelatedProduct: [],
            SortBy: '',
            SortExp: '',
            CurrentPage: 1,
            TotalPage: 0,
            TotalRecord: 0,
            noRecord: true,
            PageNumber: 1,
            PageSize: 10,
            UserId: null
        }
    },
    created: function () {

        var vm = this;
        var UserInfo = vm.GetUserInfo;
        vm.UserId = UserInfo.ID;
        if (vm.GetRelatedProduct != null && vm.GetRelatedProduct.length > 0) {

            vm.GetRelatedProductData = vm.GetRelatedProduct;

        } else {
            vm.FetchData();
        }

    },
    methods: {
        singleSelect(event, item) {
            var vm = this;

            if (event.target.checked == true) {
                vm.GetRelatedProductData.forEach(element => {                   
                    if (element.ID == item.ID) {
                        element.isSelected = true;
                        this.IsChecked = true;
                    }
                })
            } else {
                vm.GetRelatedProductData.forEach(element => {
                    if (element.ID == item.ID) {
                        element.isSelected = false;
                        this.IsChecked = true;
                    }
                })
            }
        },

        FetchData: function () {
            var vm = this;
            vm.isLoading = true;
            var url = `catId=${this.RelatedProductDaata[0].AssetCatalogueId}&type=ProductName`;
            DataService.GetRelatedProduct(url).then(response => {
                if (response.data.result.length > 0) {
                    this.GetRelatedProductData = JSON.parse(JSON.parse(response.data.result).RESULT);

                    //  this.GetRelatedProductData.forEach(row=>{
                    //     row.isCheckBoxDisabled = false;
                    //     if (row.status == 'Dispute Raised') {
                    //         row.isCheckBoxDisabled = true;
                    //         }

                    //  })

                    //this.TotalRecords = response.data.data[0].TOTAL_PAGES;
                    //this.TotalPages = Math.ceil(this.TotalRecords / this.PageSizes);
                    // this.CurrentPages = this.PageNumbers;
                    this.noRecord = false;

                } else {
                    this.noRecord = true;
                    this.GetRelatedProductData = [];
                    this.TotalRecords = 0
                }
                // setTimeout(function () {
                //     vm.CheckBoxBootstrap();
                // }, 300);
                // setTimeout(function () {
                //     vm.ResponsiveDataTable('tablelistingdata');
                // }, 400);
                // setTimeout(function () {
                //     $('#chkAll_0').trigger('click');
                //     vm.isLoading = false;
                // }, 600);

            })
        },
     

        SaveChanges: function () {
            var vm = this;
            if (vm.GetRelatedProduct != null && vm.GetRelatedProduct.length > 0) {
                vm.$parent.UpdateProductList(vm.txtAssetQuentity, vm.ItemIndex);
            } else {
                var locationId = vm.RelatedProductDaata[0].LocationId;
                var selectedProductArray = [];
                vm.AssetListData.forEach((item) => {
                    selectedProductArray.push({
                        catalogueId: item.AssetCatalogueId,
                        uniqueId: item.ParentUniqueId
                    })
                });
                vm.GetRelatedProductData.forEach((item, index) => {
                    if (vm.IsChecked) {
                        var relationType = item.ID == '0' ? 'Product' : 'ProductName';
                        var id = relationType == 'ProductName' ? item.ID : vm.RelatedProductDaata[0].ParentUniqueId;
                        // var isMandatory = item.Mandatory;
                        // var relatedCatalogueId = vm.RelatedProductDaata[0].AssetCatalogueId;
                        // var relatedUniqueId = vm.RelatedProductDaata[0].ParentUniqueId;
                        // var AssetQuentity = vm.txtAssetQuentity;
                        if (selectedProductArray.some(x => x.catalogueId == vm.RelatedProductDaata[0].AssetCatalogueId && vm.RelatedProductDaata[0].ParentUniqueId)) {
                            var catalogueIds = relationType == 'ProductName' ? id : null;
                            var uniqueIds = relationType == 'Product' ? id : null;
                            var assignedFrom = this.$options.filters.formatDate(new Date(vm.DateofAssignment));
                            var assignedTill = this.$options.filters.formatDate(new Date(vm.DateofAssignmentTillDate));
                            var IssueTo =  vm.issueTo??0
                            var startTime = this.$options.filters.formatTime(new Date(assignedFrom));
                            var endTime = this.$options.filters.formatTime(new Date(assignedTill));

                            var url = `id=&isView=1&barcode=&assetType=&assetUniqueId=&selfCheckout=&reqFrom=assetassignment&isFor=&isuniqueSearch=&issueTo=${IssueTo}&assignedFrom=${assignedFrom}
                            &assignedTill=${assignedTill}&startTime=${startTime}&endTime=${endTime}&locationId=${locationId}&RFID=&pageSize=&pageNum=&assignedFromDateTime=&assignedTillDateTime=
                            &uniqueIds=${uniqueIds}&catalogueIds=${catalogueIds}`;

                            DataService.GetCompanyAssestCatalogsDetalis(url).then((response) => {
                                vm.RelatedProduct = response.data;
                                vm.ShowAlert(vm.$t('RelatedInformationUpdate'), "success", true, vm.$t("Alert"))
                               // vm.$emit('RelatedProduct', vm.RelatedProduct);
                                vm.ClosePopup();
                            });
                        }
                    } else {
                        vm.$parent.Isrelatedproduct = false;
                    }
                });
            }
        },

        pagerMethod: function (value) {
            this.PageSize = value.PageSize;
            this.PageNum = value.PageNumber;
            this.FetchData();
        },

        sortdata: function (s) {
            var SortDir = "sort tb_headerSortDown";
            this.SortBy = s;
            if (s === this.SortBy) {
                if (this.SortExp == "") {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                } else if (this.SortExp == "ASC") {
                    this.SortExp = "DESC";
                    SortDir = "sort tb_headerSortUp";
                } else {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
            }
            if (this.activeTab == 1 || this.activeTab == 4) {
                this.FetchData();
            } else if (this.activeTab == 2) {
                this.GetAssetReplacement();
            } else {
                this.GetAssetReturnRequestList();
            }
            $("#" + s + '  span:first-child').attr("class", SortDir);
        },

        ClosePopup: function () {
            this.$parent.CloseRelatedPopup();
        },       
        commonHeaderButtonClick: function () {},
        renderActions() {},
        renderRowActionMethod() {},
    }
}
</script>

<style scoped>
input.custom-control-input {
    z-index: 1;
}

span.btn.d-inline-block.w-80.text-center.text-truncate.btn-warning {
    padding: 0;
}

span.btn.d-inline-block.w-80.h-20.text-center.text-truncate.btn-success {
    padding: 0px;
}

.p-action-btn {
    border-left: 0px solid #4d5a60;
}
</style>
